import json
import sys
import re

def resolve_path(data, path):
    components = path.split('.')
    current = data
    for component in components:
        if isinstance(current, dict) and component in current:
            current = current[component]
        elif isinstance(current, list) and component.isdigit() and int(component) < len(current):
            current = current[int(component)]
        else:
            return None
    return current

def render_template(template_path, data_path):
    with open(template_path, 'r', encoding='utf-8') as template_file:
        template = template_file.read()

    with open(data_path, 'r', encoding='utf-8') as data_file:
        data = json.load(data_file)

    def replace_match(match):
        placeholder = match.group(1)
        value = resolve_path(data, placeholder)
        if value is None:
            return '[MISSING]'
        elif isinstance(value, str):
            return value
        else:
            return json.dumps(value)

    rendered = re.sub(r'\{\{([^}]+)\}\}', replace_match, template)
    print(rendered)

if __name__ == '__main__':
    if len(sys.argv) != 3:
        print("Usage: python template_render.py <template_path> <data_path>")
