import json
import sys
import re

def resolve_path(data, path_parts):
    current = data
    for part in path_parts:
        if isinstance(current, dict):
            current = current.get(part, None)
        elif isinstance(current, list):
            try:
                current = current[int(part)]
            except (IndexError, ValueError):
                current = None
        else:
            current = None
        if current is None:
            break
    return current

def render_template(template_path, data_path):
    with open(template_path, 'r', encoding='utf-8') as template_file:
        template = template_file.read()

    with open(data_path, 'r', encoding='utf-8') as data_file:
        data = json.load(data_file)

    def replace_placeholder(match):
        path = match.group(1)
        parts = path.split('.')
        value = resolve_path(data, parts)
        if value is None:
            return '[MISSING]'
        return str(value) if isinstance(value, str) else json.dumps(value)

    rendered = re.sub(r'\{\{([^}]+)\}\}', replace_placeholder, template)
    print(rendered)

if __name__ == '__main__':
    if len(sys.argv) != 3:
        print("Usage: python template_render.py <template_file> <data_file>")
        sys.exit(1)
    render_template(sys.argv[1], sys.argv[2])
